import{_ as e,c as p,o as r,ah as i}from"./chunks/framework.Dnh4IO1K.js";const _=JSON.parse('{"title":"12、【否】 坤下乾上","description":"周易集註 - 12、【否】 坤下乾上","frontmatter":{"title":"12、【否】 坤下乾上","description":"周易集註 - 12、【否】 坤下乾上"},"headers":[],"relativePath":"classics/jizhu/016.md","filePath":"classics/jizhu/016.md"}'),t={name:"classics/jizhu/016.md"};function h(l,a,s,n,c,d){return r(),p("div",null,[...a[0]||(a[0]=[i('<h1 id="_12、【否】-坤下乾上" tabindex="-1">12、【否】 坤下乾上 <a class="header-anchor" href="#_12、【否】-坤下乾上" aria-label="Permalink to “12、【否】 坤下乾上”">​</a></h1><p>否者閉塞不通也，卦象卦德皆與泰反。《序卦》“物不可以終通，故受之以否”，所以次泰。此七月之卦。</p><p>否之匪人，與履虎尾同人於野艮其背同例，卦辭惟此四卦與卦名相連。否之匪人者，言否之者非人也，乃天也，即大往小來也。不利者，即彖辭，萬物不通，天下無邦，道長道消也。君子貞者，即儉德避難，不可榮以祿也。不言小人者，易為君子謀也。大往小來者，否泰相綜，泰內卦之陽，往而居否之外，外卦之陰，來而居否之內也。文王當殷之末世，親見世道之否，所以髮匪人之句。後來孔子居春秋之否，乃曰道之將行也與命也，道之將廢也與命也。孟子居戰國之否，乃曰莫之為而為者天也，莫之致而致者命也，皆宗文王否之匪人之句。否之匪人者天數也，君子貞者人事也，所以孔孟進以禮，退以義，惟守君子之貞。程朱以為非人道也，似無道字意。誠齋以為用非其人，似無用字意。不如只就大往小來說。</p><p>言否之者非人也，乃天也。否由於天，所以佔者不利。丁否運之君子，欲濟其否，豈容智力於間哉，惟當守其正而已。何也?大往小來，匪人也，乃天運之自然也。天運既出於自然，君子亦將為之何哉!故惟當守其正而已。</p><p>《彖》曰：否之匪人，不利，君子貞。大往小來，則是天地不交，而萬物不通也。上下不交，而天下無邦也。內陰而外陽，內柔而外剛，內小人而外君子，小人道長，君子道消也。</p><p>釋大往小來四字，與泰卦同。上自為上，下自為下，則雖有國，實與無邦國同矣，故天下無邦。</p><h3 id="《象》曰-天地不交-否。君子以儉德闢難-不可榮以祿。-闢音避-難去聲" tabindex="-1">《象》曰：天地不交，否。君子以儉德闢難，不可榮以祿。(闢音避，難去聲) <a class="header-anchor" href="#《象》曰-天地不交-否。君子以儉德闢難-不可榮以祿。-闢音避-難去聲" aria-label="Permalink to “《象》曰：天地不交，否。君子以儉德闢難，不可榮以祿。(闢音避，難去聲)”">​</a></h3><p>儉者，儉約其德，斂其首先之光也。坤為吝嗇，儉之象也。闢難者，避小人之禍也。三陽出居在外，避難之象也。不可榮以祿者，人不可得而榮之以祿也，非戒辭也。言若不儉德，則人因德而榮祿，小人忌之，禍即至矣。今既儉德，人不知我，則不榮以祿，故不禁以祿者，正所以避難也。</p><p>初六，拔茅茹，以其匯，貞吉亨。</p><p>變震為蕃，茅茹之象也。否綜泰，故初爻辭同。貞者，上有九五剛健中正之君，三陰能牽連而志在於君則貞矣。蓋否之時，能從乎陽，是小人能從君子，豈不貞。</p><p>初在下，去陽甚遠，三陰同體，故有拔茅茹以其匯之象。當否之時，能正而志在於休否之君，吉而且亨之道也，故教佔者以此。</p><h3 id="《象》曰-拔茅貞吉-志在君也。" tabindex="-1">《象》曰：拔茅貞吉，志在君也。 <a class="header-anchor" href="#《象》曰-拔茅貞吉-志在君也。" aria-label="Permalink to “《象》曰：拔茅貞吉，志在君也。”">​</a></h3><p>貞者以其志在於君也，故吉。泰初九曰志在外，此變外為君者，泰六五之君，不如否之剛健中正，得稱君也。</p><p>六二，包承，小人吉，大人否亨。</p><p>包承者，包乎初也。二乃初之承，曰包承者，猶言將承包之也。大來乎下，故曰包荒，小來乎下，故曰包承。既包乎承，則小人與小人為群矣。小人與小人為群，大人與大人為群，不相干涉，不相傷害矣。否者不榮以祿也。</p><p>當否之時，小來乎下，故六二有包承之象。既包乎承，則小人為群，不上害乎大人矣，故佔者在小人則有不害正之吉，在大人則身否而道亨也。</p><h3 id="《象》曰-大人否亨-不亂群也。" tabindex="-1">《象》曰：大人否亨，不亂群也。 <a class="header-anchor" href="#《象》曰-大人否亨-不亂群也。" aria-label="Permalink to “《象》曰：大人否亨，不亂群也。”">​</a></h3><p>陰來乎下，陽往乎上，兩不相交，故不亂群。</p><p>六三，包羞。</p><p>包者，包乎二也。三見二包乎其初，三即包乎二，殊不知二隔乎陽，故包同類，若三則親比乎陽矣。從陽可也，乃不從陽，非正道矣，可羞者也，故曰包羞。</p><p>六三不中不正，親比乎陽，當小來於下之時，止知包乎其下矣，而不知上有陽剛之大人在也，乃舍四之大人而包二之小人，羞孰甚焉，故有是象。佔者之羞可知矣。</p><h3 id="《象》曰-包羞-位不當也。" tabindex="-1">《象》曰：包羞，位不當也。 <a class="header-anchor" href="#《象》曰-包羞-位不當也。" aria-label="Permalink to “《象》曰：包羞，位不當也。”">​</a></h3><p>位不當者，柔而志剛，不能順從乎君子，故可羞。</p><p>九四，有命無咎，疇離祉。</p><p>變巽為命，命之象也。有命者，受九五之命也。四近君，居多懼之地，易於獲咎。今變巽順，則能從乎五矣，故有命無咎。疇者，同類之三陽也。離者麗也，離祉者，附麗其福祉也。</p><p>九四當否過中之時，剛居乎柔，能從休否之君，同濟乎否，則因大君之命，而濟否之志行矣。故不惟在我無咎，獲一身之慶，而同類亦並受其福也。故其象佔如此。</p><h3 id="《象》曰-有命無咎-志行也。" tabindex="-1">《象》曰：有命無咎，志行也。 <a class="header-anchor" href="#《象》曰-有命無咎-志行也。" aria-label="Permalink to “《象》曰：有命無咎，志行也。”">​</a></h3><p>濟否之志行。</p><p>九五，休否，大人吉。其亡其亡，繫於苞桑。</p><p>休否者，休息其否也。其亡其亡者，念念不忘其亡，惟恐其亡也。人依木息曰休，中爻巽木，五居木之上，休之象也。巽為陰木，二居巽之下，陰木柔，桑之象也。巽為繩，系之象也。叢生曰苞，叢者聚也。柔條細弱，群聚而成叢者也。此爻變離合坎，為叢棘，苞之象也。桑止可取葉養蠶，不成其木已，非樟楠松柏之大矣，又況叢聚而生，則至小而至柔者也。以國家之大，不繫於磐石之堅固，而繫於苞桑之柔小，危之甚也，即危如累卵之意。此二句有音韻，或古語也。</p><p>九五陽剛中正，能休時之否，大人之事也，故大人遇之則吉。然下應乎否，惟休否而已，未傾否也，故必勿恃其否之可休，勿安其休之為吉。兢業戒懼，念念惟恐其亡，若國家系於苞桑之柔小，常畏其亡，而不自安之象，如此則否休而漸傾矣。故教佔者，必儆戒如此，繫於苞桑，又其亡其亡之象也。</p><h3 id="《象》曰-大人之吉-位正當也。" tabindex="-1">《象》曰：大人之吉，位正當也。 <a class="header-anchor" href="#《象》曰-大人之吉-位正當也。" aria-label="Permalink to “《象》曰：大人之吉，位正當也。”">​</a></h3><p>有中正之德而又居尊位，與夬履同者，亦恐有所恃，故爻辭有其亡其亡之句。</p><p>上九，傾否，先否後喜。</p><p>上文言休息其否，則其否猶未盡也。傾者倒也，與鼎之顛趾同言顛倒也。本在下，而今反在上也。否泰乃上下相綜之卦，泰陰上陽下，泰終則復隍，陽反在上，而否矣。否，陽上陰下，否終則傾倒，陰反在上而泰矣，此傾字之意也。復隍復字，應無往不復復字。傾否傾字，應無平不陂陂字。陂者傾邪也，周公爻辭，其精極矣。變兌成悅，喜之象也。</p><p>上九以陽剛之才，居否之終，傾時之否，乃其優為者，故其佔為先否後喜。</p><h3 id="《象》曰-否終則傾-何可長也。" tabindex="-1">《象》曰：否終則傾，何可長也。 <a class="header-anchor" href="#《象》曰-否終則傾-何可長也。" aria-label="Permalink to “《象》曰：否終則傾，何可長也。”">​</a></h3><p>言無久否之理。</p>',38)])])}const m=e(t,[["render",h]]);export{_ as __pageData,m as default};
